<script>
  import { onMount, tick } from 'svelte';
  import { SAMPLE_TEXT, STYLE_OPTIONS, CATEGORIES, parseMenu, getStyle, validateBrief, slugify } from '$lib/menu.mjs';
  import { buildSVG, svgPageCount } from '$lib/svg.mjs';
  import {buildDigitalHtml} from '$lib/digital.mjs';
  import {pdfPayload} from '$lib/pdf-payload.mjs';
  import { SOURCE_REPO } from '$lib/catalog.mjs';
  let refs=[]; let catalogError=''; let loading=true; let category='all'; let search=''; let favoritesOnly=false; let selected=[];
  let currentIndex=0; let gallery; let notice=''; let exporting=false;
  let restaurant='Juniper & Stone';let tagline='A TABLE WORTH COMING BACK TO';let subtitle='SEASONAL KITCHEN';
  let menuText=SAMPLE_TEXT;let styleId='editorial';let chosenPackage='signature';let currency='$';let footer='Please tell us about allergies · Prices subject to change.';
  let printRegion='United States';let printSize='Letter';let printQty='100';let siteURL='';let briefEmail='';
  let showBuilder=true;
  let previewSVG='';let filtered=[];let menuItems=[];let issues=[];let theme=STYLE_OPTIONS[0];let pageCount=1;
  const packages=[{id:'refresh',name:'The Refresh',price:79,tag:'QUICK FIX',items:'Up to 25 items · pages based on length',description:'An improved menu without a full rebrand.',details:'1 original layout · 2 revisions · PDF + PNG + editable SVG/JSON'},{id:'signature',name:'The Signature',price:179,tag:'MOST REQUESTED',items:'Up to 60 items · pages based on length',description:'A complete menu that feels like your restaurant.',details:'2 concepts · 3 revisions · print + digital package'},{id:'launch',name:'The Full Table',price:399,tag:'COMPLETE LAUNCH',items:'Up to 100 items · pages based on length',description:'The whole menu system, ready for launch.',details:'Bilingual option · 2 formats · print handoff · 3 revisions'}];
  const printLinks=[{name:'FedEx Office',why:'Upload your finished menu and choose paper, size, and quantity.',url:'https://www.office.fedex.com/default/menus.html',type:'Direct printing · no affiliate'}, {name:'MustHaveMenus',why:'Dedicated menu print service with an affiliate application.',url:'https://www.musthavemenus.com/content/affiliate',type:'Affiliate application required'}, {name:'MOO',why:'Reseller and affiliate options for premium printed materials.',url:'https://www.moo.com/us/partner',type:'Partner application required'}];
  onMount(async()=>{try{const r=await fetch('/api/catalog'); const data=await r.json(); if(!r.ok)throw Error(data.error||'Catalog unavailable'); refs=data.items; }catch(e){catalogError=e?.message||'Unable to load references'} finally{loading=false;} });
  $: filtered=refs.filter(r=>(category==='all'||r.cat===category)&&(!favoritesOnly||selected.some(x=>x.href===r.href))&&(`${r.title} ${r.by} ${r.note}`.toLowerCase().includes(search.toLowerCase())));
  $: menuItems=parseMenu(menuText);
  $: theme=getStyle(styleId);
  $: {
    const currentBrief={restaurant,tagline,subtitle,menuText,styleId,footer,currency,printSize};
    issues=validateBrief(currentBrief).issues;
    try {
      pageCount=svgPageCount(currentBrief);
      previewSVG=buildSVG(currentBrief,0);
    } catch (error) {
      pageCount=0;
      previewSVG='';
      issues=[...issues, 'Layout cannot fit this content: '+(error instanceof Error ? error.message : String(error))];
    }
  }
  function toggleRef(r){selected=selected.some(x=>x.href===r.href)?selected.filter(x=>x.href!==r.href):[...selected,r].slice(0,8);notice=`${selected.length} reference${selected.length===1?'':'s'} saved to the design brief.`}
  function presetFrom(r){const lookup={mex:'cantina',vintage:'editorial',photo:'modern',elegant:'editorial',boards:'noir',canva:'botanical'};styleId=lookup[r.cat]||'editorial';toggleRef(r);}
  function moveSlider(dir){if(gallery)gallery.scrollBy({left:dir*340,behavior:'smooth'});currentIndex=Math.max(0,currentIndex+dir)}
  function getBrief(){return {version:1,restaurant:restaurant.trim(),tagline,subtitle,menuText,styleId,currency,footer,package:chosenPackage,printRegion,printSize,printQty,siteURL,contactEmail:briefEmail,references:selected.map(x=>({number:x.num,title:x.title,by:x.by,href:x.href,category:x.cat})),sourceLicenseNotice:'Inspiration links are reference-only. Do not copy third-party artwork without separate permission.',approval:{clientPricesConfirmed:false,finalDesignApproved:false},production:{status:'draft',requiresPreflight:true}}}
  function download(name,content,type){const blob=content instanceof Blob?content:new Blob([content],{type});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
  function exportBrief(){const brief=getBrief();download(`${slugify(restaurant)}-agent-brief.json`,JSON.stringify(brief,null,2),'application/json');notice='Editable project brief downloaded. Prices remain unapproved until the client confirms them.'}
  async function exportSVG(){const b=getBrief();const count=svgPageCount(b);if(count===1){download(`${slugify(b.restaurant)}-menu.svg`,buildSVG(b,0),'image/svg+xml');notice='Editable SVG exported.';return;}const JSZip=(await import('jszip')).default;const z=new JSZip();for(let i=0;i<count;i++)z.file(`menu-page-${i+1}.svg`,buildSVG(b,i));download(`${slugify(b.restaurant)}-svg-pages.zip`,await z.generateAsync({type:'blob'}),'application/zip');notice=`All ${count} editable SVG pages exported.`}
  async function getPDF(brief){const r=await fetch('/api/export/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pdfPayload(brief))});if(!r.ok){const data=await r.json();throw Error(data.error||'PDF generation failed');}return await r.blob()}
  async function exportPDF(){try{exporting=true;const b=getBrief();const pdf=await getPDF(b);download(`${slugify(b.restaurant)}-print-proof.pdf`,pdf,'application/pdf');notice='PDF generated: 3mm bleed and crop marks. Have the printer confirm RGB handling, trim, and paper specifications before printing.'}catch(e){notice=e.message||'Export failed'}finally{exporting=false}}
  async function svgToPNG(svg,renderPrintSize){return new Promise((resolve,reject)=>{const b=new Blob([svg],{type:'image/svg+xml'});const u=URL.createObjectURL(b);const img=new Image();img.onload=()=>{try{const c=document.createElement('canvas');const letter=renderPrintSize==='Letter';c.width=letter?2550:2480;c.height=letter?3300:3508;const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);c.toBlob(blob=>{URL.revokeObjectURL(u);if(blob)resolve(blob);else reject(Error('PNG conversion failed'))},'image/png',1)}catch(e){URL.revokeObjectURL(u);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(u);reject(Error('SVG render failed'))};img.src=u})}
  async function exportPack(){try{exporting=true;const b=getBrief();const count=svgPageCount(b);const frozenItems=parseMenu(b.menuText);const v=validateBrief(b);if(!v.ok)throw Error(v.issues.slice(0,4).join(' '));const JSZip=(await import('jszip')).default;const z=new JSZip();z.file('project-brief.json',JSON.stringify(b,null,2));z.file('menu-items.json',JSON.stringify(frozenItems,null,2));z.file('digital/mobile-menu.html',buildDigitalHtml(b));z.file('prepress/checklist.txt','CARTAPRESS PRINT HANDOFF\n1. Confirm all item names, prices, translations and allergen disclosures with the owner.\n2. Confirm trim '+(b.printSize==='Letter'?'US Letter 8.5x11 inches':'A4 210x297mm')+', 3mm bleed, paper and finishes with the chosen printer.\n3. PDF is RGB and requires provider-specific CMYK and font preflight.\n4. Print one legible full-size proof before ordering quantity.\n5. Never reproduce third-party gallery artwork.\n');z.file('READ-ME-FIRST.txt',`CartaPress Studio original export for ${b.restaurant}\nReferences are inspiration only, not reusable artwork.\nProof all descriptions, prices, allergens, dimensions and print color conversion.\nPrint PDF contains 3mm bleed and crop marks but uses RGB, not CMYK.\nDo not print without confirming your printer's requirements.\nYour editable source: .svg files and project-brief.json.\n`);for(let n=0;n<count;n++){const id=String(n+1).padStart(2,'0');const svg=buildSVG(b,n);z.file(`svg/menu-${id}.svg`,svg);z.file(`png/menu-${id}-300dpi.png`,await svgToPNG(svg,b.printSize));}z.file('pdf/print-proof.pdf',await getPDF(b)); if(b.siteURL.trim()){const url=new URL(b.siteURL);if(url.protocol!=='https:'||!url.hostname.includes('.'))throw Error('QR link requires a public HTTPS URL you control.');const QRCode=(await import('qrcode')).default;z.file('qr/menu-link-qr.svg',await QRCode.toString(url.href,{type:'svg',width:900,margin:2,errorCorrectionLevel:'H'}));}
    const blob=await z.generateAsync({type:'blob'});download(`${slugify(b.restaurant)}-menu-production-package.zip`,blob,'application/zip');notice=`Exported ${count} SVGs + PNGs, portable mobile HTML, structured JSON, PDF proof and printer checklist.`}catch(e){notice=e.message||'Bundle failed'}finally{exporting=false}}
  function exportHtml(){const b=getBrief();const v=validateBrief(b);if(!v.ok){notice=v.issues.slice(0,2).join(' ');return;}download(`${slugify(restaurant)}-digital-menu.html`,buildDigitalHtml(b),'text/html');notice='Self-contained mobile menu exported. Host it on your own website or share the HTML file.';}
  async function copyPicks(){const s=selected.map(x=>`#${x.num} ${x.title} by ${x.by} — ${x.href}`).join('\n')||'No references selected';try{await navigator.clipboard.writeText(s);notice='Reference shortlist copied.'}catch{download('references.txt',s,'text/plain');notice='Reference shortlist downloaded.'}}
  function jump(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
</script>
<svelte:head><title>CartaPress Studio | A menu your guests will remember</title><meta name="description" content="Design original restaurant menus, explore 190 credited visual references, and download editable, high-resolution print files. An AI-ready studio for restaurants." /></svelte:head>
<div class="site-shell">
  <div class="announcement"><span class="tiny-spark">✳</span> A SMALL STUDIO FOR THE BIGGEST PART OF YOUR TABLE <span class="linelet"></span> MENU DESIGN · PRINT · DIGITAL</div>
  <header class="topbar"><a class="brand" href="/" aria-label="CartaPress Studio Home"><span class="brand-symbol">C<span class="dot">.</span></span><span class="brand-word">CARTA<span>PRESS</span><small>STUDIO</small></span></a><nav class="navlinks" aria-label="Main navigation"><button on:click={()=>jump('gallery')}>Inspiration</button><button on:click={()=>jump('studio')}>The studio</button><button on:click={()=>jump('pricing')}>Packages</button><button on:click={()=>jump('print')}>Printing</button></nav><button class="nav-cta" on:click={()=>jump('studio')}>Design your menu <span>↗</span></button></header>
  <main>
    <section class="hero" aria-label="Beautifully designed printed menus on a restaurant table"><div class="hero-copy"><div class="eyebrow"><span class="asterisk">✳</span> FOR RESTAURANTS WITH SOMETHING TO SAY</div><h1>Make the<br/><em>first impression</em><br/>appetizing<span class="punct">.</span></h1><p>Beautiful menus, without the back-and-forth. Find a direction you love. Give us the dishes. Get an original menu ready for the table, the screen, and the printer.</p><div class="hero-actions"><button class="btn-solid" on:click={()=>jump('gallery')}>Explore the menu gallery <span>↗</span></button><button class="btn-plain" on:click={()=>jump('studio')}>Try the menu studio <span>↗</span></button></div><div class="hero-foot"><span class="pillstar">✳</span><span>Made for independent restaurants, cafés, bars & food trucks</span></div></div></section>
    <section class="ticker"><div class="ticker-inner"><span>DESIGNED TO BE READ</span><span>✳</span><span>MADE TO BE REMEMBERED</span><span>✳</span><span>BUILT FOR THE REAL WORLD</span><span>✳</span><span>PRINT + DIGITAL</span></div></section>
    <section class="inspiration section-pad" id="gallery"><div class="section-head"><div><div class="eyebrow dark">01 / FIND YOUR DIRECTION</div><h2>Great taste<br/><em>starts with a feeling.</em></h2><p>Explore {loading?'a curated library':refs.length+' credited references'} from independent designers. Save up to eight favorites to your brief. Our studio creates a new design inspired by your direction—not a copy.</p></div><div class="gallery-counter"><span class="big-number">{loading?'···':refs.length||'190'}</span><span>REFERENCES<br/>TO EXPLORE</span></div></div>
      <div class="filter-panel"><div class="filter-cats">{#each Object.entries(CATEGORIES) as [id,name]}<button class:active={category===id} on:click={()=>category=id}>{name}</button>{/each}</div><div class="filter-tools"><input aria-label="Search inspiration" type="search" placeholder="Search a design or artist…" bind:value={search}/><button class:active={favoritesOnly} on:click={()=>favoritesOnly=!favoritesOnly}>♡ My picks ({selected.length})</button></div></div>
      <div class="gallery-toolbar"><span>{loading?'Loading credited references…':`${filtered.length} design directions`}</span><div><button aria-label="Scroll gallery left" on:click={()=>moveSlider(-1)}>←</button><button aria-label="Scroll gallery right" on:click={()=>moveSlider(1)}>→</button></div></div>
      {#if catalogError}<div class="catalog-error"><strong>The reference feed is temporarily unavailable.</strong><p>{catalogError}. See the <a href="https://franlopz.github.io/menu-inspiration/" target="_blank" rel="noopener noreferrer">original 190-design gallery</a>. All original designs and client exports remain available.</p></div>{/if}
      <div class="card-rail" bind:this={gallery} aria-label="Menu design inspiration carousel">{#each filtered as r (r.num)}<article class="inspo-card"><div class="inspo-image"><img loading="lazy" alt="{r.title}, menu inspiration by {r.by}" src={r.thumb}/><span class="ref-id">REF {String(r.num).padStart(3,'0')}</span><button class:chosen={selected.some(x=>x.href===r.href)} aria-label="Select design inspiration {r.title}" on:click={()=>presetFrom(r)}>{selected.some(x=>x.href===r.href)?'✓ Saved':'+ Save style'}</button></div><div class="inspo-meta"><div><div class="card-category">{CATEGORIES[r.cat]||r.cat}</div><h3>{r.title}</h3><p>By {r.by}</p></div><a href={r.href} target="_blank" rel="noopener noreferrer" aria-label="View original design {r.title} by {r.by}">↗</a></div></article>{/each}</div>
      <div class="inspo-foot"><p><strong>Reference-only gallery.</strong> Original artwork remains credited and hosted by its creators; selection never transfers commercial usage rights. <a href={SOURCE_REPO} target="_blank" rel="noopener noreferrer">Source project ↗</a></p><div><button on:click={copyPicks}>Copy picks ↗</button><button class="btn-small" on:click={()=>jump('studio')}>Use {selected.length} references in my brief →</button></div></div>
    </section>
    <section class="studio-section section-pad" id="studio"><div class="section-head"><div><div class="eyebrow">02 / YOUR MENU, YOUR WAY</div><h2>The design studio<span class="punct">.</span></h2><p>Try your own menu here. Edit the name, descriptions and prices, choose an original design direction, and download a production package.</p></div><span class="studio-side">NO SIGN-UP FOR THE DEMO<br/>PDF PROOFS USE SERVER PROCESSING</span></div><p class="privacy-notice">PDF exports send the restaurant name, menu content, visual style and print settings to this server for rendering. Contact email is excluded from that request; other previews and local downloads are produced in your browser.</p><div class="studio-layout"><div class="form-col" id="menu-edit-form"><div class="mobile-preview-jump"><button type="button" on:click={()=>jump("menu-live-preview")} aria-controls="menu-live-preview">See live menu preview <span aria-hidden="true">↓</span></button></div><div class="panel-heading"><span>01</span><strong>Make it yours</strong></div><label>RESTAURANT NAME<input bind:value={restaurant} maxlength="36" placeholder="Your restaurant" /></label><label>ONE-LINE STORY<input bind:value={tagline} maxlength="64" placeholder="Something worth coming back for" /></label><label>MENU LABEL<input bind:value={subtitle} maxlength="40" placeholder="Lunch · Dinner · Cocktails" /></label><label>YOUR MENU <small>Format: ITEM | DESCRIPTION | PRICE · headings in UPPERCASE · or paste MenuVision structured JSON</small><textarea rows="14" bind:value={menuText}></textarea></label><div class="form-help">{menuItems.length} items across {new Set(menuItems.map(x=>x.section)).size} sections · {pageCount} exported page{pageCount===1?'':'s'}</div><div class="panel-heading"><span>02</span><strong>Choose a visual direction</strong></div><div class="style-picks">{#each STYLE_OPTIONS as s}<button class:active={styleId===s.id} on:click={()=>styleId=s.id}><span class="swatch" style:background={s.paper} style:border-color={s.accent}><i style:background={s.ink}></i></span><span>{s.title}<small>{s.label}</small></span>{#if styleId===s.id}<b>✓</b>{/if}</button>{/each}</div><div class="panel-heading"><span>03</span><strong>Prepare for delivery</strong></div><div class="twocol"><label>MENU CURRENCY<select bind:value={currency}><option value="$">$ · USD</option><option value="MX$">MX$ · MXN</option><option value="€">€ · EUR</option><option value="£">£ · GBP</option></select></label><label>PRINT REGION<select bind:value={printRegion}><option>United States</option><option>Mexico</option><option>Canada</option><option>Other</option></select></label><label>PAGE SIZE<select bind:value={printSize}><option value="Letter">US Letter · 8.5×11 in</option><option value="A4">A4 · 210×297 mm</option></select></label><label>PRINT QUANTITY<select bind:value={printQty}><option>50</option><option>100</option><option>250</option><option>500</option><option>1000</option></select></label></div><label>PUBLIC MENU URL <small>Optional · creates a QR asset in your bundle</small><input type="url" bind:value={siteURL} placeholder="https://yourrestaurant.com/menu"/></label><label>CONTACT EMAIL <small>Optional · stays in your downloaded brief; never sent for PDF conversion</small><input type="email" bind:value={briefEmail} placeholder="owner@restaurant.com"/></label><div class="validation">{#if issues.length===0}<span>✓ Ready for draft export. Final print proof is still required.</span>{:else}<strong>Before export:</strong><ul>{#each issues.slice(0,3) as issue}<li>{issue}</li>{/each}{#if issues.length>3}<li>+ {issues.length-3} more checks</li>{/if}</ul>{/if}</div></div><div class="preview-col" id="menu-live-preview"><div class="mobile-edit-back"><button type="button" on:click={()=>jump("menu-edit-form")}>↑ Back to editing</button></div><div class="preview-top"><div><span class="live-dot"></span> LIVE ART DIRECTION <span class="preview-style">{theme.title}</span></div><span>FIRST PAGE / {pageCount}</span></div><div class="paper-stage"><div class="preview-art">{@html previewSVG}</div></div><div class="download-box"><div class="download-head"><span>YOUR DELIVERY FILES</span><span>ORIGINAL ASSETS ONLY</span></div><div class="file-icons"><span>PDF</span><span>SVG</span><span>PNG</span><span>JSON</span><span>ZIP</span><span>HTML</span></div><button class="primary-download" disabled={exporting} on:click={exportPack}>{exporting?'Preparing your package…':'Download production package'} <span>↘</span></button><div class="download-row"><button disabled={exporting} on:click={exportPDF}>PDF proof ↗</button><button on:click={exportSVG}>SVG master ↗</button><button on:click={exportBrief}>Agent brief ↗</button><button on:click={exportHtml}>Mobile HTML ↗</button></div><p>ZIP includes a portable, searchable mobile HTML menu. PDF uses 3mm bleed and crop marks, but RGB is not a certified CMYK press proof. Verify size, fonts and colors with your print provider. Files are created for your own menu, never copied from the inspiration gallery.</p></div></div></div></section>
    <section class="how-section section-pad"><div class="eyebrow dark">03 / HOW IT WORKS</div><h2>Three good decisions.<br/><em>One beautiful menu.</em></h2><div class="steps"><article><span>01</span><h3>Pick your direction</h3><p>Choose the mood that fits your room, food and people. We use your references to understand the feeling, not duplicate someone else's work.</p></article><article><span>02</span><h3>Send us the details</h3><p>Share your dishes, verified prices, logo and printer preferences. Our agent prepares a custom draft and checks it against your brief.</p></article><article><span>03</span><h3>Approve, download, print</h3><p>Review the design and approve the final proof. Receive editable files and print-ready deliverables, with printing as an optional separate order.</p></article></div></section>
    <section class="pricing-section section-pad" id="pricing"><div class="section-head"><div><div class="eyebrow">04 / ONE-OFF PROJECTS, NO SURPRISES</div><h2>A good menu is<br/><em>good business.</em></h2><p>Clear, fixed-scope packages for Fiverr, Upwork or direct clients. Printing and third-party subscriptions are separate.</p></div></div><div class="price-grid">{#each packages as pkg}<article class:featured={pkg.id==='signature'} class:chosen={chosenPackage===pkg.id} class="price-card"><div class="price-top"><span>{pkg.tag}</span>{#if pkg.id==='signature'}<span>POPULAR CHOICE</span>{/if}</div><h3>{pkg.name}</h3><p>{pkg.description}</p><div class="money"><sup>$</sup>{pkg.price}<span>USD / project</span></div><div class="package-items">{pkg.items}</div><p class="package-details">{pkg.details}</p><button on:click={()=>{chosenPackage=pkg.id;jump('studio')}}>Choose {pkg.name} <span>↗</span></button></article>{/each}</div><p class="pricing-note">Project turnaround is scoped when the order is accepted; complex typesetting, photography and printing may be quoted separately. No guaranteed revenue or sales outcomes.</p></section>
    <section class="print-section section-pad" id="print"><div class="section-head"><div><div class="eyebrow dark">05 / FROM SCREEN TO TABLE</div><h2>Make it real<span class="punct">.</span></h2><p>Take your approved PDF to a menu printer. These independent providers let you investigate paper, quantities and shipping. We currently use ordinary partner links—not active affiliate tracking.</p></div></div><div class="print-grid">{#each printLinks as partner}<article><span>PRINT ROUTE ↗</span><h3>{partner.name}</h3><p>{partner.why}</p><small>{partner.type}</small><a href={partner.url} target="_blank" rel="noopener noreferrer">View provider <span>↗</span></a></article>{/each}</div><div class="print-disclosure">PARTNER TRANSPARENCY — No referral affiliation is active. If tracked partner links are introduced, we will label them clearly. Printing, shipping, taxes and physical-quality checks remain with the selected provider.</div></section>
    <section class="closing"><div class="closing-kicker">READY FOR THE NEXT SERVICE?</div><h2>Your best seller<br/>deserves <em>better paper.</em></h2><button on:click={()=>jump('studio')}>Make a menu worth keeping <span>↗</span></button><div class="closing-symbol">✳</div></section>
  </main>
  <footer><div class="footer-main"><div class="footer-brand"><b>CARTAPRESS</b> STUDIO<span>Design for the part of the restaurant guests take home in their memory.</span></div><div class="footer-links"><a href="#gallery">Inspiration</a><a href="#studio">Studio</a><a href="#pricing">Packages</a><a href="#print">Print options</a></div><div class="footer-legal">Independent design service · Third-party art used only as credited inspiration · Client owns approved custom deliverables, subject to agreed license and payment terms.</div></div><div class="footer-bottom"><span>© 2026 CartaPress Studio · Development brand; trademark availability not verified</span><span>CREATED FOR RESTAURANTS WITH CHARACTER</span></div></footer>
  {#if notice}<div class="toast" role="status"><button on:click={()=>notice=''} aria-label="Dismiss notification">×</button>{notice}</div>{/if}
</div>
<style>
